        if (EDGE_GSPREAD) { if (!cloned) { const int fpc = GOV_VIS * clone_every, nin = fpc - 1 > 0 ? fpc - 1 : 1; int ph = GOV_VIS * frames_since_clone - 1; if (ph < 0) ph = 0; nb = edge_take_phb(batch, nb, ph % nin, nin, &rw, cap); } }
        else if (cloned) nb = edge_take_b(batch, nb, 0, &rw, cap);
